import ij.gui.PolygonRoi;import ij.gui.Roi;import ij.process.ShortProcessor;import java.io.*;import java.nio.file.*;import java.security.*;import java.util.zip.*;
public class PolygonRasterReview {
 public static void main(String[]a)throws Exception{try(DataInputStream in=new DataInputStream(new GZIPInputStream(Files.newInputStream(Path.of(a[0]))))){if(in.readInt()!=0x47415450||in.readInt()!=1)throw new AssertionError();int w=in.readInt(),h=in.readInt(),n=in.readInt();PolygonRoi[]ps=new PolygonRoi[n];for(int i=0;i<n;i++){in.readFloat();in.readFloat();int rays=in.readInt();float[]x=new float[rays],y=new float[rays];for(int k=0;k<rays;k++){x[k]=in.readFloat();y[k]=in.readFloat();}ps[i]=new PolygonRoi(x,y,rays,Roi.POLYGON);}if(in.read()!=-1)throw new AssertionError();ShortProcessor raster=new ShortProcessor(w,h);for(int i=n-1;i>=0;i--){raster.setColor(i+1);raster.fill(ps[i]);}MessageDigest md=MessageDigest.getInstance("SHA-256");try(DataOutputStream out=new DataOutputStream(Files.newOutputStream(Path.of(a[1])))){for(short v:(short[])raster.getPixels()){out.writeShort(v);md.update((byte)((v&65535)>>>8));md.update((byte)v);}}StringBuilder s=new StringBuilder();for(byte b:md.digest())s.append(String.format("%02x",b&255));System.out.println("labels="+n+" raster_sha256="+s);}}
}
